405	## #{#wsp3b authority=developer} Register Wealth Simple Parser in Factory
406	
407	**Description:**  
408	The CSVParserFactory must support Wealth Simple parser for both direct lookup (getParser) and auto-detection (detectParser).
409	
410	**Authority Level:** developer  
411	**Priority:** High
412	
413	**Acceptance Criteria:**
414	
415	1. Add import for WealthSimpleParser in CSVParserFactory
416	2. Add case for 'Wealth Simple' in getParser() switch statement
417	3. Add WealthSimpleParser to detectParser() parsers array
418	4. Add WealthSimpleParser to getAllParsers() return array
419	5. Position appropriately in auto-detection order (before more generic parsers)
420	
421	**Implementation:**
422	
423	```typescript
424	// In src/lib/services/csvParsers/CSVParserFactory.ts
425	
426	import { WealthSimpleParser } from './WealthSimpleParser'; // NEW
427	
428	export class CSVParserFactory {
429		static getParser(creditCardType: CreditCardType): ICSVParser {
430			switch (creditCardType) {
431				case 'PC Financial':
432					return new PCFinancialParser();
433				case 'American Express':
434					return new AmexParser();
435				case 'RBC Financial':
436					return new RBCFinancialParser();
437				case 'TD Bank':
438					return new TDBankParser();
439				case 'Simplii Financial':
440					return new SimpliiFinancialParser();
441				case 'EQ Bank':
442					return new EQBankParser();
443				case 'Wealth Simple': // NEW
444					return new WealthSimpleParser();
445				default:
446					throw new Error(`Unsupported credit card type: ${creditCardType}`);
447			}
448		}
449	
450		static detectParser(csvContent: string): {
451			parser: ICSVParser;
452			creditCardType: CreditCardType;
453		} | null {
454			const parsers: Array<{ parser: ICSVParser; type: CreditCardType }> = [
455				{ parser: new AmexParser(), type: 'American Express' },
456				{ parser: new PCFinancialParser(), type: 'PC Financial' },
457				{ parser: new RBCFinancialParser(), type: 'RBC Financial' },
458				{ parser: new SimpliiFinancialParser(), type: 'Simplii Financial' },
459				{ parser: new EQBankParser(), type: 'EQ Bank' },
460				{ parser: new WealthSimpleParser(), type: 'Wealth Simple' }, // NEW
461				{ parser: new TDBankParser(), type: 'TD Bank' }
462			];
463	
464			for (const { parser, type } of parsers) {
465				if (parser.validateFormat(csvContent)) {
466					return { parser, creditCardType: type };
467				}
468			}
469	
470			return null;
471		}
472	
473		static getAllParsers(): ICSVParser[] {
474			return [
475				new PCFinancialParser(),
476				new AmexParser(),
477				new RBCFinancialParser(),
478				new TDBankParser(),
479				new SimpliiFinancialParser(),
480				new EQBankParser(),
481				new WealthSimpleParser() // NEW
482			];
483		}
484	}
485	```
