8	/**
9	 * Helper: create an XLSX ArrayBuffer from an array of arrays (rows).
10	 * First row is treated as headers.
11	 */
12	function createXLSXBuffer(data: (string | number)[][]): ArrayBuffer {
13		const ws = XLSX.utils.aoa_to_sheet(data);
14		const wb = XLSX.utils.book_new();
15		XLSX.utils.book_append_sheet(wb, ws, 'Sheet1');
16		const out = XLSX.write(wb, { type: 'array', bookType: 'xlsx' });
17		return out as ArrayBuffer;
18	}
19	
